# -*- coding: utf-8 -*-
import json
import sys
from pathlib import Path

# Add REPO_ROOT to path
REPO_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(REPO_ROOT / "build"))
from importlib.machinery import SourceFileLoader
check_locales = SourceFileLoader("check_locales", str(REPO_ROOT / "build" / "check-locales.py")).load_module()

def debug_key(k, en_val, ru_val):
    en_spans = check_locales.extract_spans(en_val)
    ru_spans = check_locales.extract_spans(ru_val)
    en_tags = check_locales.extract_tags(en_val)
    ru_tags = check_locales.extract_tags(ru_val)
    print(f"KEY: {k}")
    print(f"  EN tags: {dict(en_tags)}")
    print(f"  RU tags: {dict(ru_tags)}")
    print(f"  EN spans ({len(en_spans)}): {en_spans}")
    print(f"  RU spans ({len(ru_spans)}): {ru_spans}")

