out_path = REPO_ROOT / "src/Mod/assets/scribe/lang/ru.json"
with open(out_path, "w", encoding="utf-8") as f:
    json.dump(ru_data, f, ensure_ascii=False, indent="\t")
    f.write("\n")

print(f"Wrote {len(ru_data)} keys to {out_path}")

en = check_locales.load_json(check_locales.EN_PATH)
en_req = [k for k in en if not check_locales.is_comment_key(k) and not check_locales.is_optional_flavor_key(k)]
en_opt = [k for k in en if not check_locales.is_comment_key(k) and check_locales.is_optional_flavor_key(k)]
crossrefs = check_locales.build_crossrefs(en)

errors = check_locales.check_locale("ru", out_path, en, en_req, en_opt, crossrefs)
if errors:
    print(f"Validation failed with {len(errors)} error(s):")
    for e in errors:
        print(f"  - {e}")
    sys.exit(1)
else:
    print("Validation PASSED successfully for ru.json!")
